import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const OTPVerify = () => {
  const [otp, setOtp] = useState(["", "", "", "", "", ""]);

  const handleChange = (index, value) => {
    if (!/^[0-9]?$/.test(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    if (value && index < 5) {
      document.getElementById(`otp-input-${index + 1}`).focus();
    }
  };

  const handleSubmit = () => {
    alert(`Entered OTP: ${otp.join("")}`);
  };

  return (
    <div className="container d-flex justify-content-center align-items-center vh-100">
      <div className="card p-4 shadow-lg text-center" style={{ width: "400px",background:"linear-gradient(135deg, #004aad, #00204a)"  }}>
        <h3 style={{ color:"white"  }} className="text-primary">OTP Verify</h3>
        <p style={{ color:"white"  }}>Your code was sent to you via Phone number</p>
        <div className="d-flex justify-content-center mb-3">
          {otp.map((digit, index) => (
            <input
              key={index}
              id={`otp-input-${index}`}
              type="text"
              className="form-control text-center mx-1"
              style={{ width: "40px", height: "40px", fontSize: "20px" }}
              maxLength="1"
              value={digit}
              onChange={(e) => handleChange(index, e.target.value)}
            />
          ))}
        </div>
        <button className="btn btn-primary w-100" onClick={handleSubmit}>
          Verify
        </button>
        <p style={{ color:"white"  }} className="mt-2">
          Don't receive code? Resend code
        </p>
      </div>
    </div>
  );
};

export default OTPVerify;
